<?php namespace App\Models;use Illuminate\Database\Eloquent\Factories\HasFactory;use Illuminate\Foundation\Auth\User as Authenticatable;use Illuminate\Notifications\Notifiable;use Laravel\Sanctum\HasApiTokens;class User extends Authenticatable{use HasFactory,Notifiable,HasApiTokens;protected $fillable=['name','email','password','role','phone','permissions','two_factor_enabled','two_factor_secret','referral_code','referred_by'];protected $hidden=['password','remember_token','two_factor_secret'];protected function casts():array{return ['email_verified_at'=>'datetime','password'=>'hashed','two_factor_enabled'=>'boolean'];}public function orders(){return $this->hasMany(Order::class);}public function addresses(){return $this->hasMany(Address::class);}public function reviews(){return $this->hasMany(Review::class);}public function wishlistItems(){return $this->hasMany(Wishlist::class);}public function vendor(){return $this->hasOne(Vendor::class);}public function loyalty(){return $this->hasOne(LoyaltyAccount::class);}public function isAdmin():bool{return $this->role==='admin';}public function isVendor():bool{return $this->role==='vendor'||$this->vendor()->where('status','approved')->exists();}}
